// Minimal stand-in for @minecraft/server-ui used by tools/smoke_test.mjs.
// Tests push the answers a player would give onto __answers; every form shown
// is recorded in __shown.
export const __answers = [];
export const __shown = [];
class Form {
  constructor(kind) { this.kind = kind; this.data = { buttons: [], fields: [] }; }
  title(t) { this.data.title = t; return this; }
  body(b) { this.data.body = b; return this; }
  button(b) { this.data.buttons.push(b); return this; }
  button1(b) { this.data.buttons[0] = b; return this; }
  button2(b) { this.data.buttons[1] = b; return this; }
  textField(label, placeholder) { this.data.fields.push(label); return this; }
  async show() {
    __shown.push({ kind: this.kind, ...this.data });
    const a = __answers.shift();
    if (a === undefined) return { canceled: true, cancelationReason: "UserClosed" };
    if (typeof a === "function") return a(this.data);
    if (Array.isArray(a)) return { canceled: false, formValues: a };
    return { canceled: false, selection: typeof a === "string" ? this.data.buttons.findIndex((b) => b.includes(a)) : a };
  }
}
export class ActionFormData extends Form { constructor() { super("action"); } }
export class MessageFormData extends Form { constructor() { super("message"); } }
export class ModalFormData extends Form { constructor() { super("modal"); } }
